    16	    public FinanceNotificationListener(NotificationService notificationService) {
    17	        this.notificationService = notificationService;
    18	    }
    19	
    20	    @Override
    21	    public void onEvent(ReservationEvent event) {
    22	        if (event instanceof ReservationConfirmedEvent confirmedEvent) {
    23	            sendPaymentNotification(confirmedEvent);
    24	        } else if (event instanceof ReservationCancelledEvent cancelledEvent) {
    25	            if (cancelledEvent.wasConfirmed() && hasRefund(cancelledEvent.getRefundAmount())) {
    26	                sendRefundNotification(cancelledEvent);
    27	            }
    28	        }
    29	    }
    30	
    31	    private void sendPaymentNotification(ReservationConfirmedEvent event) {
    32	        notificationService.sendFinancePaymentEmail(event.getReservation(), event.getTotal());
    33	    }
    34	
    35	    private void sendRefundNotification(ReservationCancelledEvent event) {
    36	        notificationService.sendFinanceRefundEmail(event.getReservation(), event.getRefundAmount());
    37	    }
    38	
    39	    private boolean hasRefund(Money refundAmount) {
    40	        return refundAmount.getAmount().compareTo(BigDecimal.ZERO) > 0;
    41	    }
    42	}
