    20	               .append(" | Saída: ").append(DateFormatter.formatBR(reservation.getCheckOut()))
    21	               .append(" | ").append(reservation.getNights())
    22	               .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
