    22	
    23	    public String generateOccupancyReport(LocalDate date) {
    24	        List<Reservation> reservations = reservationRepository.findPaidByNight(date);
    25	        List<Room> allRooms = roomService.getAllRooms();
    26	
    27	        StringBuilder csv = new StringBuilder();
    28	        csv.append("room,type,reservation,check_in,check_out\n");
    29	
    30	        for (Reservation reservation : reservations) {
    31	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    32	            csv.append(room.getNumber()).append(",")
    33	               .append(room.getType()).append(",")
    34	               .append(reservation.getId()).append(",")
    35	               .append(DateFormatter.formatISO(reservation.getCheckIn())).append(",")
    36	               .append(DateFormatter.formatISO(reservation.getCheckOut())).append("\n");
    37	        }
    38	
    39	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
    40	
    41	        return csv.toString();
    42	    }
    43	
    44	    public String generateRevenueReport(YearMonth month) {
    45	        List<Reservation> reservations = reservationRepository.findByMonth(month);
    46	
    47	        StringBuilder csv = new StringBuilder();
    48	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    49	
    50	        Money totalRevenue = new Money(BigDecimal.ZERO);
    51	
    52	        for (Reservation reservation : reservations) {
    53	            Money revenue = calculateRevenue(reservation);
    54	            totalRevenue = totalRevenue.add(revenue);
    55	
    56	            csv.append(reservation.getId()).append(",")
    57	               .append(reservation.getRoomNumber()).append(",")
    58	               .append(DateFormatter.formatISO(reservation.getCheckIn())).append(",")
    59	               .append(DateFormatter.formatISO(reservation.getCheckOut())).append(",")
    60	               .append(reservation.getStatus()).append(",")
    61	               .append(revenue.getAmount()).append("\n");
    62	        }
    63	
    64	        csv.append("total,").append(totalRevenue.getAmount());
    65	
    66	        return csv.toString();
    67	    }
    68	
    69	    private Money calculateRevenue(Reservation reservation) {
    70	        Money paid = reservation.getAmountPaid();
    71	        Money refunded = reservation.getRefund() != null ? reservation.getRefund() : new Money(BigDecimal.ZERO);
    72	        return paid.subtract(refunded);
    73	    }
    74	}
