    24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    25	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    26	                                        int guests, RatePlan ratePlan) {
    27	        Room room = roomService.getRoomByNumber(roomNumber);
    28	        if (room == null) {
    29	            throw new RoomNotFoundException();
    30	        }
    31	
    32	        if (guests < 1) {
    33	            throw new InvalidRequestException("Invalid number of guests");
    34	        }
    35	
    36	        if (guests > room.getCapacity()) {
    37	            throw new CapacityExceededException();
    38	        }
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    41	            throw new InvalidRequestException("Check-out must be after check-in");
    42	        }
    43	
    44	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    45	            throw new RoomUnavailableException();
    46	        }
    47	
    48	        long id = reservationRepository.nextId();
    49	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail,
    50	            guestCpf, checkIn, checkOut, guests, ratePlan);
    51	
    52	        return reservationRepository.save(reservation);
    53	    }
    54	
    55	    public Reservation getReservation(long id) {
