    53	    public List<Reservation> findByMonth(YearMonth month) {
    54	        LocalDate start = month.atDay(1);
    55	        LocalDate end = month.atEndOfMonth();
    56	
    57	        return reservations.stream()
    58	            .filter(r -> !r.getCheckIn().isBefore(start) && !r.getCheckIn().isAfter(end))
    59	            .filter(r -> r.getStatus() != ReservationStatus.PENDING)
    60	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    61	                .thenComparing(Reservation::getId))
    62	            .toList();
