    23	
    24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    25	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    26	                                        int guests, RatePlan ratePlan) {
    27	        Room room = roomService.getRoomByNumber(roomNumber);
    28	        if (room == null) {
    29	            throw new RoomNotFoundException();
    30	        }
    31	
    32	        if (guests < 1) {
    33	            throw new InvalidRequestException("Invalid number of guests");
    34	        }
    35	
    36	        if (guests > room.getCapacity()) {
    37	            throw new CapacityExceededException();
    38	        }
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    41	            throw new InvalidRequestException("Check-out must be after check-in");
    42	        }
    43	
    44	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    45	            throw new RoomUnavailableException();
    46	        }
    47	
    48	        long id = reservationRepository.nextId();
    49	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail,
    50	            guestCpf, checkIn, checkOut, guests, ratePlan);
    51	
    52	        return reservationRepository.save(reservation);
    53	    }
    54	
    55	    public Reservation getReservation(long id) {
    56	        return reservationRepository.findById(id)
    57	            .orElseThrow(ReservationNotFoundException::new);
    58	    }
    59	
    60	    public Reservation confirmReservation(long id) {
    61	        Reservation reservation = getReservation(id);
    62	
    63	        if (!reservation.canConfirm()) {
    64	            throw new OperationNotAllowedException();
    65	        }
    66	
    67	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    68	        Money subtotal = reservation.calculateSubtotal(room.getNightlyRate());
    69	        Money discount = reservation.calculateDiscount(subtotal);
    70	        Money total = reservation.calculateTotal(subtotal, discount);
    71	
    72	        reservation.confirm(total);
    73	
    74	        eventPublisher.publish(new ReservationConfirmedEvent(reservation, total));
    75	
    76	        return reservation;
    77	    }
    78	
    79	    public Reservation cancelReservation(long id) {
    80	        Reservation reservation = getReservation(id);
    81	
    82	        if (!reservation.canCancel()) {
    83	            throw new OperationNotAllowedException();
    84	        }
    85	
    86	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
    87	        Money refundAmount = reservation.cancel();
    88	
    89	        eventPublisher.publish(new ReservationCancelledEvent(reservation, refundAmount, wasConfirmed));
    90	
    91	        return reservation;
    92	    }
    93	
    94	    public Reservation checkIn(long id) {
    95	        Reservation reservation = getReservation(id);
    96	
    97	        if (!reservation.canCheckIn()) {
    98	            throw new OperationNotAllowedException();
    99	        }
   100	
   101	        reservation.checkIn();
   102	        return reservation;
   103	    }
