   116	    private boolean isRoomAvailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   117	        LocalDate current = checkIn;
   118	        while (current.isBefore(checkOut)) {
   119	            if (!reservationRepository.findActiveByRoomAndNight(roomNumber, current).isEmpty()) {
   120	                return false;
   121	            }
   122	            current = current.plusDays(1);
   123	        }
   124	        return true;
   125	    }
