     1	package com.pousada.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public class Reservation {
     8	    private final long id;
     9	    private final String roomNumber;
    10	    private final String guestName;
    11	    private final String guestEmail;
    12	    private final String guestCpf;
    13	    private final LocalDate checkIn;
    14	    private final LocalDate checkOut;
    15	    private final int guests;
    16	    private final RatePlan ratePlan;
    17	
    18	    private ReservationStatus status;
    19	    private Money amountPaid;
    20	    private Money refund;
    21	
    22	    public Reservation(long id, String roomNumber, String guestName, String guestEmail,
    23	                      String guestCpf, LocalDate checkIn, LocalDate checkOut,
    24	                      int guests, RatePlan ratePlan) {
    25	        this.id = id;
    26	        this.roomNumber = roomNumber;
    27	        this.guestName = guestName;
    28	        this.guestEmail = guestEmail;
    29	        this.guestCpf = guestCpf;
    30	        this.checkIn = checkIn;
    31	        this.checkOut = checkOut;
    32	        this.guests = guests;
    33	        this.ratePlan = ratePlan;
    34	        this.status = ReservationStatus.PENDING;
    35	        this.amountPaid = new Money(BigDecimal.ZERO);
    36	        this.refund = null;
    37	    }
    38	
    39	    public int getNights() {
    40	        return (int) checkIn.until(checkOut).getDays();
    41	    }
    42	
    43	    public Money calculateSubtotal(Money nightlyRate) {
    44	        Money total = new Money(BigDecimal.ZERO);
    45	        LocalDate current = checkIn;
    46	
    47	        while (current.isBefore(checkOut)) {
    48	            Money rate = nightlyRate;
    49	            if (isHighSeason(current)) {
    50	                rate = rate.multiply(new BigDecimal("1.20"));
    51	            }
    52	            total = total.add(rate);
    53	            current = current.plusDays(1);
    54	        }
    55	
    56	        return total;
    57	    }
    58	
    59	    public Money calculateDiscount(Money subtotal) {
    60	        if (ratePlan.getDiscountRate().compareTo(BigDecimal.ZERO) == 0) {
    61	            return new Money(BigDecimal.ZERO);
    62	        }
    63	        return subtotal.multiply(ratePlan.getDiscountRate());
    64	    }
    65	
    66	    public Money calculateTotal(Money subtotal, Money discount) {
    67	        return subtotal.subtract(discount);
    68	    }
    69	
    70	    private boolean isHighSeason(LocalDate date) {
    71	        Month month = date.getMonth();
    72	        int day = date.getDayOfMonth();
    73	
    74	        if (month == Month.DECEMBER && day >= 15) {
    75	            return true;
    76	        }
    77	
    78	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
