    16	    private final AtomicLong idGenerator = new AtomicLong(1);
    17	
    18	    public Reservation save(Reservation reservation) {
    19	        reservations.add(reservation);
    20	        return reservation;
    21	    }
    22	
    23	    public Optional<Reservation> findById(long id) {
