     8	import java.util.ArrayList;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	import java.util.Optional;
    12	import java.util.concurrent.atomic.AtomicLong;
    13	
    14	public class ReservationRepository {
    15	    private final List<Reservation> reservations = new ArrayList<>();
    16	    private final AtomicLong idGenerator = new AtomicLong(1);
    17	
    18	    public Reservation save(Reservation reservation) {
    19	        reservations.add(reservation);
    20	        return reservation;
    21	    }
    22	
    23	    public Optional<Reservation> findById(long id) {
    24	        return reservations.stream()
    25	            .filter(r -> r.getId() == id)
    26	            .findFirst();
    27	    }
    28	
    29	    public List<Reservation> findAll() {
    30	        return new ArrayList<>(reservations);
    31	    }
    32	
    33	    public long nextId() {
    34	        return idGenerator.getAndIncrement();
    35	    }
    36	
    37	    public List<Reservation> findActiveByRoomAndNight(String roomNumber, LocalDate night) {
    38	        return reservations.stream()
    39	            .filter(r -> r.getRoomNumber().equals(roomNumber))
    40	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
    41	            .filter(r -> r.occupiesNight(night))
    42	            .toList();
    43	    }
    44	
    45	    public List<Reservation> findPaidByNight(LocalDate night) {
    46	        return reservations.stream()
    47	            .filter(Reservation::isPaid)
    48	            .filter(r -> r.occupiesNight(night))
    49	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    50	            .toList();
    51	    }
    52	
    53	    public List<Reservation> findByMonth(YearMonth month) {
    54	        LocalDate start = month.atDay(1);
    55	        LocalDate end = month.atEndOfMonth();
    56	
    57	        return reservations.stream()
    58	            .filter(r -> !r.getCheckIn().isBefore(start) && !r.getCheckIn().isAfter(end))
    59	            .filter(r -> r.getStatus() != ReservationStatus.PENDING)
    60	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    61	                .thenComparing(Reservation::getId))
    62	            .toList();
    63	    }
    64	}
